import { AxisScale } from '@visx/axis';

import { isTimeframe } from './is-timeframe.js';
import { MINIMUM_MARKER_WIDTH } from '../../annotations-atoms/constants.js';
import { AnnotationData } from '../types/annotations.js';

export const getMarkerProps = (
  markerData: AnnotationData,
  scale: AxisScale<number>,
) => {
  const isTimeframedAnnotation = isTimeframe(markerData);
  const [domainStart, domainEnd] = scale.domain();

  const x0 =
    markerData.start.getTime() < domainStart
      ? scale(domainStart) ?? 0
      : scale(markerData.start.getTime()) ?? 0;

  if (isTimeframedAnnotation) {
    return getTimeframeMarkerProps(markerData, scale, domainEnd, x0);
  }

  return { x: x0, width: 0 };
};

const getTimeframeMarkerProps = (markerData, scale, domainEnd, x0) => {
  const time = markerData.end?.getTime() ?? markerData.start?.getTime();
  const x1 = scale(time > domainEnd ? domainEnd : time) ?? 0;
  const pillWidth = Math.abs(x1 - x0);

  let x = x0;
  let width = pillWidth;

  if (pillWidth < MINIMUM_MARKER_WIDTH) {
    width = MINIMUM_MARKER_WIDTH;
    x = x0 - (MINIMUM_MARKER_WIDTH - pillWidth) / 2;
  }

  return { x, width };
};
